"""Fixed-price bundles; all prices and savings are in cents."""

from .catalog import product


# code: (name, {sku: quantity}, price in cents)
BUNDLES = {
    'STARTER': ('Starter pack', {'MUG': 1, 'TEE': 1}, 3299),
    'TRAVEL': ('Travel set', {'CAP': 1, 'BAG': 1}, 2099),
}


def apply_bundles(items):
    """Return ({code: count}, remaining items) without changing the input.

    Apply each bundle as many times as possible, in alphabetical code order.
    Items use the cart's uppercase SKUs and nonnegative integer quantities.
    """
    rest = {sku: qty for sku, qty in items.items() if qty}
    bundles = {}
    for code in sorted(BUNDLES):
        _, components, _ = BUNDLES[code]
        count = min(rest.get(sku, 0) // qty for sku, qty in components.items())
        if count:
            bundles[code] = count
            for sku, qty in components.items():
                rest[sku] -= count * qty
                if rest[sku] == 0:
                    del rest[sku]
    return bundles, rest


def bundle_savings(code):
    """Return the saving in cents for one bundle (KeyError for unknown codes)."""
    _, components, price = BUNDLES[code]
    return sum(product(sku)[1] * qty for sku, qty in components.items()) - price

import unittest
from unittest.mock import patch

from shop.bundles import BUNDLES, apply_bundles, bundle_savings


class BundlesTest(unittest.TestCase):
    def test_definitions_and_savings(self):
        self.assertEqual(BUNDLES, {
            'STARTER': ('Starter pack', {'MUG': 1, 'TEE': 1}, 3299),
            'TRAVEL': ('Travel set', {'CAP': 1, 'BAG': 1}, 2099),
        })
        self.assertEqual(bundle_savings('STARTER'), 450)
        self.assertEqual(bundle_savings('TRAVEL'), 399)
        with self.assertRaises(KeyError):
            bundle_savings('UNKNOWN')

    def test_empty_and_zero_quantities(self):
        self.assertEqual(apply_bundles({}), ({}, {}))
        self.assertEqual(apply_bundles({'MUG': 0, 'TEE': 1}), ({}, {'TEE': 1}))

    def test_incomplete_bundles(self):
        items = {'MUG': 3, 'BAG': 2}
        self.assertEqual(apply_bundles(items), ({}, items))

    def test_exact_bundles(self):
        self.assertEqual(apply_bundles({'MUG': 1, 'TEE': 1, 'CAP': 1, 'BAG': 1}),
                         ({'STARTER': 1, 'TRAVEL': 1}, {}))

    def test_repeated_bundles_and_leftovers_preserve_input(self):
        items = {'MUG': 5, 'TEE': 3, 'CAP': 2, 'BAG': 4}
        original = items.copy()
        bundles, rest = apply_bundles(items)
        self.assertEqual(bundles, {'STARTER': 3, 'TRAVEL': 2})
        self.assertEqual(list(bundles), ['STARTER', 'TRAVEL'])
        self.assertEqual(rest, {'MUG': 2, 'BAG': 2})
        self.assertEqual(items, original)
        self.assertIsNot(rest, items)

    def test_alphabetical_priority_and_component_quantities(self):
        # Reverse insertion order and shared components make priority observable.
        definitions = {
            'Z_LAST': ('Last', {'MUG': 1}, 100),
            'A_FIRST': ('First', {'MUG': 2, 'TEE': 1}, 2000),
        }
        with patch.dict(BUNDLES, definitions, clear=True):
            bundles, rest = apply_bundles({'MUG': 5, 'TEE': 3})
            self.assertEqual(bundles, {'A_FIRST': 2, 'Z_LAST': 1})
            self.assertEqual(list(bundles), ['A_FIRST', 'Z_LAST'])
            self.assertEqual(rest, {'TEE': 1})
            self.assertEqual(bundle_savings('A_FIRST'), 2999)


if __name__ == '__main__':
    unittest.main()
